    overview.addEventListener('click',()=>{const positions=records.map(r=>[r.coordinates.lat,r.coordinates.lon]);if(preparedBounds)positions.push([preparedBounds[0],preparedBounds[1]],[preparedBounds[2],preparedBounds[3]]);if(positions.length)map.fitBounds(positions,{padding:[20,20],maxZoom:15});});
    controls.appendChild(overview);
    if(!chosen)return;
    const metadata=chosen.map_overlay,b=metadata.bounds_wgs84,bounds=[[b[1],b[0]],[b[3],b[2]]];
    localSceneLayer=L.imageOverlay(assetURL(metadata.path),bounds,{opacity:1,interactive:false,className:'regional-scene-overlay'}).addTo(map);
